input.command:
$root = "E:\.1 Work Stations\RootMC"
# Faster find: only depth-limited dirs that aren't huge handoffs/worlds
$skip = @('Server Live Backups','Server Handoffs','node_modules','.gradle','build','target','worlds','logs')
$found = [System.Collections.Generic.List[string]]::new()
function Scan-Dir($path, $depth) {
  if ($depth -gt 6) { return }
  try {
    if (Test-Path (Join-Path $path '.git')) { $found.Add((Join-Path $path '.git')); return }
    Get-ChildItem -LiteralPath $path -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
      if ($skip -contains $_.Name) { return }
      Scan-Dir $_.FullName ($depth+1)
    }
  } catch {}
}
Scan-Dir $root 0
$found | Sort-Object
Write-Output "COUNT=$($found.Count)"
# also check sibling Work Stations for RootRecord mobile
Write-Output "---SIBLING---"
Get-ChildItem "E:\.1 Work Stations" -Directory -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name
Get-ChildItem "D:\.1 Work Stations" -Directory -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name
Write-Output "---old Mobile contents---"
cmd /c "dir /b `"E:\old\Mobile`" 2>nul & dir /b `"D:\old\Mobile`" 2>nul"

$ErrorActionPreference = 'Continue'
$repos = @(
  'E:\.1 Work Stations\RootMC\emergent-repo',
  'E:\.1 Work Stations\RootMC\Marketing'
) + (Get-ChildItem 'E:\.1 Work Stations\RootMC\github-plugin-repos\staging' -Directory | ForEach-Object { $_.FullName })

$out = @()
foreach ($r in $repos) {
  if (-not (Test-Path (Join-Path $r '.git'))) { continue }
  Push-Location $r
  try {
    $branch = (git rev-parse --abbrev-ref HEAD 2>$null)
    $sha = (git rev-parse --short HEAD 2>$null)
    $dirty = (git status --porcelain 2>$null)
    $dirtyN = if ($dirty) { ($dirty | Measure-Object).Count } else { 0 }
    $remote = (git remote get-url origin 2>$null)
    $ab = ''
    if ($remote) {
      git fetch --quiet origin 2>$null | Out-Null
      $ab = (git rev-list --left-right --count '@{u}...HEAD' 2>$null)
      if (-not $ab) {
        $track = (git status -sb 2>$null | Select-Object -First 1)
        $ab = "no-upstream|$track"
      } else {
        $parts = $ab -split '\s+'
        $ab = "behind=$($parts[0]) ahead=$($parts[1])"
      }
    } else { $ab = 'no-remote' }
    $name = Split-Path $r -Leaf
    $out += [pscustomobject]@{ Repo=$name; Branch=$branch; SHA=$sha; Dirty=$dirtyN; Sync=$ab; Remote=([string]$remote).Replace('https://github.com/','') }
  } finally { Pop-Location }
}
$out | Format-Table -AutoSize | Out-String -Width 220
Write-Output "DIRTY_REPOS:"
$out | Where-Object { $_.Dirty -gt 0 -or $_.Sync -match 'ahead=[1-9]' -or $_.Sync -match 'no-upstream' } | Format-Table -AutoSize | Out-String -Width 220

# Mobile suite git repos
$mobileRoots = @('E:\old\Mobile','D:\old\Mobile')
foreach ($mr in $mobileRoots) {
  Write-Output "=== SCAN $mr ==="
  Get-ChildItem $mr -Directory -ErrorAction SilentlyContinue | ForEach-Object {
    $g = Join-Path $_.FullName '.git'
    if (Test-Path $g) { "GIT: $($_.FullName)" }
    # one level nested apps/
  }
  if (Test-Path "$mr\apps") {
    Get-ChildItem "$mr\apps" -Directory -ErrorAction SilentlyContinue | ForEach-Object {
      if (Test-Path (Join-Path $_.FullName '.git')) { "GIT: $($_.FullName)" }
    }
  }
}
# Also check if Mobile itself is a git repo
@('E:\old\Mobile','D:\old\Mobile') | ForEach-Object {
  if (Test-Path "$_\.git") { "ROOT_GIT: $_" } else { "NO_ROOT_GIT: $_" }
}
# Minecraft-Marketing
@('E:\.1 Work Stations\Minecraft-Marketing','D:\.1 Work Stations\Minecraft-Marketing') | ForEach-Object {
  if (Test-Path "$_\.git") { "MARKETING_GIT: $_" }
}
# How plugins sync
Select-String -Path "E:\.1 Work Stations\RootMC\scripts\publish-plugin-github-repos.ps1" -Pattern "git |origin|push|Plugin Building|staging" | Select-Object -First 40 Line
# ava push overview
Get-Content "E:\.1 Work Stations\RootMC\Web Files\rootmc-ava\scripts\ava-github-push.mjs" -TotalCount 80
# REPO-INDEX
Get-Content "E:\.1 Work Stations\RootMC\github-plugin-repos\REPO-INDEX.md" -TotalCount 80

# Commit plugins with -c identity (no git config writes)
$msg = @"
pre-SSD cutover: sync staging sources before workstation wipe
"@
$staging = 'E:\.1 Work Stations\RootMC\github-plugin-repos\staging'
$report = @()
foreach ($name in @('root-appreciation','root-economy','root-gamble','root-loans','root-perms')) {
  Push-Location (Join-Path $staging $name)
  Write-Output "==== $name ===="
  git status --porcelain
  git add -A
  git diff --cached --quiet
  if ($LASTEXITCODE -ne 0) {
    git -c user.email="dev@rootrecord.info" -c user.name="RootRecord" commit -m $msg 2>&1 | Out-String | Write-Output
    if ($LASTEXITCODE -eq 0) {
      git push origin HEAD:main 2>&1 | Out-String | Write-Output
      $report += "$name|$(git rev-parse --short HEAD)|push=$LASTEXITCODE"
    } else {
      $report += "$name|COMMIT_FAIL|$LASTEXITCODE"
    }
  } else {
    $report += "$name|$(git rev-parse --short HEAD)|clean_or_unstaged"
  }
  Pop-Location
}
Write-Output "REPORT:"; $report

Push-Location E:\
$paths = @(
  '.1 Work Stations/RootMC/Web Files/rootmc-api',
  '.1 Work Stations/RootMC/Web Files/rootmc-web',
  '.1 Work Stations/RootMC/Web Files/rootmc-realm-api',
  '.1 Work Stations/RootMC/Web Files/rootmc-webstat-proxy',
  '.1 Work Stations/RootMC/Web Files/rootmc-minecraft-map',
  '.1 Work Stations/RootMC/Web Files/rootmc-app',
  '.1 Work Stations/RootMC/Change Logs',
  '.1 Work Stations/RootMC/WORKSPACE.md',
  '.1 Work Stations/RootMC/GEN-1-GEN-2.md',
  '.1 Work Stations/RootMC/Mobile App Files/rootmc-android',
  '.1 Work Stations/RootMC/Plugin Building/Minecraft'
)
foreach ($p in $paths) {
  if (Test-Path -LiteralPath $p) {
    git add -A -- $p
    Write-Output "ADDED $p"
  } else {
    Write-Output "MISS $p"
  }
}
git diff --cached --name-only | ForEach-Object {
  if ($_ -match '(^|/)\.env(\.|$)|google-services\.json|\.jks$|\.keystore$|node_modules|/build/|/\.gradle/|cloud\.yml$|database\.yml$') {
    git reset HEAD -- $_ 2>$null | Out-Null
    Write-Output "UNSTAGE $_"
  }
}
$staged = (git diff --cached --name-only | Measure-Object).Count
Write-Output "STAGED_COUNT=$staged"
git diff --cached --stat | Select-Object -Last 20
if ($staged -gt 0) {
  git -c user.email="dev@rootrecord.info" -c user.name="RootRecord" commit -m "pre-SSD cutover: snapshot RootMC web/plugin/android source trees (no secrets)" 2>&1 | Select-Object -Last 20
  Write-Output "COMMIT_EXIT=$LASTEXITCODE HEAD=$(git rev-parse --short HEAD)"
  git push https://github.com/RootRecord/MonoRepo.git HEAD:main 2>&1
  Write-Output "PUSH_EXIT=$LASTEXITCODE"
  git ls-remote https://github.com/RootRecord/MonoRepo.git refs/heads/main
}
Pop-Location

# Ensure no git procs; clear lock; complete source snapshot
Get-CimInstance Win32_Process -Filter "Name='git.exe'" -ErrorAction SilentlyContinue | ForEach-Object {
  Write-Output "KILL $($_.ProcessId)"
  Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}
Start-Sleep 3
Remove-Item -Force 'E:\.git\index.lock' -ErrorAction SilentlyContinue
Write-Output "LOCK_GONE=$(-not (Test-Path 'E:\.git\index.lock'))"

Push-Location E:\
# Keep WORKSPACE staged if still
$files = @(
  '.1 Work Stations/RootMC/Web Files/rootmc-api/package.json',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/package-lock.json',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/tsconfig.json',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/wrangler.toml',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/deploy.ps1',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/.gitignore',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/STRIPE-WEBHOOK.md',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/d1-apply-live-remote.ps1',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/d1-apply-remote.ps1',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/d1-apply-webstat-remote.ps1'
)
foreach ($f in $files) { if (Test-Path -LiteralPath $f) { git add -- $f } }
foreach ($d in @(
  '.1 Work Stations/RootMC/Web Files/rootmc-api/migrations',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/migrations-live',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/migrations-webstat',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/scripts',
  '.1 Work Stations/RootMC/Web Files/rootmc-api/src',
  '.1 Work Stations/RootMC/Change Logs',
  '.1 Work Stations/RootMC/GEN-1-GEN-2.md',
  '.1 Work Stations/RootMC/WORKSPACE.md'
)) { if (Test-Path -LiteralPath $d) { git add -A -- $d } }

# web: add excluding node_modules by adding known children
$web = '.1 Work Stations/RootMC/Web Files/rootmc-web'
if (Test-Path $web) {
  Get-ChildItem -LiteralPath $web -Force | Where-Object { $_.Name -notin @('node_modules','dist','.wrangler','build') } | ForEach-Object {
    git add -A -- $_.FullName.Substring(3)  # strip E:\
  }
}
# Fix path - FullName is E:\.1 ... need relative from E:\
Get-ChildItem -LiteralPath $web -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -notin @('node_modules','dist','.wrangler','build') } | ForEach-Object {
  $rel = $_.FullName.Substring((Get-Location).Path.Length).TrimStart('\')
  git add -A -- $rel
}

foreach ($proj in @('rootmc-realm-api','rootmc-webstat-proxy','rootmc-minecraft-map','rootmc-app')) {
  $base = ".1 Work Stations/RootMC/Web Files/$proj"
  if (-not (Test-Path $base)) { continue }
  Get-ChildItem -LiteralPath $base -Force | Where-Object { $_.Name -notin @('node_modules','dist','.wrangler','build','.gradle') } | ForEach-Object {
    $rel = $_.FullName.Substring((Get-Location).Path.Length).TrimStart('\')
    git add -A -- $rel
  }
}

# android
$and = '.1 Work Stations/RootMC/Mobile App Files/rootmc-android'
if (Test-Path $and) {
  Get-ChildItem -LiteralPath $and -Force | Where-Object { $_.Name -notin @('build','.gradle','node_modules') } | ForEach-Object {
    $rel = $_.FullName.Substring((Get-Location).Path.Length).TrimStart('\')
    git add -A -- $rel
  }
}

# plugins - source only per plugin folder
$mc = '.1 Work Stations/RootMC/Plugin Building/Minecraft'
if (Test-Path $mc) {
  Get-ChildItem -LiteralPath $mc -Force | Where-Object { $_.Name -notin @('build','.gradle','node_modules','out','jars','run') } | ForEach-Object {
    $rel = $_.FullName.Substring((Get-Location).Path.Length).TrimStart('\')
    if ($_.PSIsContainer -and $_.Name -eq 'plugins') {
      Get-ChildItem $_.FullName -Directory | ForEach-Object {
        $prel = $_.FullName.Substring((Get-Location).Path.Length).TrimStart('\')
        # add plugin sources without build
        Get-ChildItem $_.FullName -Force | Where-Object { $_.Name -notin @('build','.gradle','out','bin') } | ForEach-Object {
          $srel = $_.FullName.Substring((Get-Location).Path.Length).TrimStart('\')
          git add -A -- $srel
        }
      }
    } else {
      git add -A -- $rel
    }
  }
}

git diff --cached --name-only | ForEach-Object {
  if ($_ -match 'node_modules|/build/|/\.gradle/|/dist/|\.jar$|google-services\.json|\.jks$|\.keystore$|cloud\.yml$|database\.yml$|(^|/)\.env(\.|$)') {
    git reset -q HEAD -- $_
  }
}
$total = (git diff --cached --name-only | Measure-Object).Count
$nm = (git diff --cached --name-only | Where-Object { $_ -match 'node_modules' } | Measure-Object).Count
Write-Output "TOTAL_STAGED=$total NODE_MODULES=$nm"
git diff --cached --name-only | ForEach-Object { ($_ -split '[\\/]')[3] } | Group-Object | Sort-Object Count -Descending | Select-Object -First 15 Name,Count
if ($total -gt 0 -and $nm -eq 0) {
  git -c user.email="dev@rootrecord.info" -c user.name="RootRecord" commit -m "pre-SSD cutover: snapshot RootMC web/plugin/android source trees (no secrets)"
  Write-Output "HEAD=$(git rev-parse --short HEAD)"
  git push https://github.com/RootRecord/MonoRepo.git HEAD:main
  Write-Output "PUSH_EXIT=$LASTEXITCODE"
  git ls-remote https://github.com/RootRecord/MonoRepo.git refs/heads/main
}
Pop-Location

# Wait for background commit/push to finish
for ($i=0; $i -lt 60; $i++) {
  Start-Sleep 5
  $t = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233069.txt" -Tail 25 -ErrorAction SilentlyContinue
  if ($t -match 'exit_code|PUSH_EXIT|TOTAL_STAGED|HEAD=') {
    $tail = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233069.txt" -Tail 40
    $tail
    if ($tail -match 'exit_code:') { break }
  }
  if ($i % 6 -eq 0) { Write-Output "still waiting... $i" }
}

Get-Process -Id 20888 -ErrorAction SilentlyContinue | Select-Object Id, ProcessName, CPU, StartTime
Get-CimInstance Win32_Process -Filter "Name='git.exe' OR Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -match '233069|RootMC|git add|pre-SSD' } | Select-Object ProcessId, Name, @{n='Cmd';e={$_.CommandLine.Substring(0,[Math]::Min(180,$_.CommandLine.Length))}}
Get-Item 'E:\.git\index.lock' -ErrorAction SilentlyContinue | Select-Object Length, LastWriteTime

Remove-Item -Force 'E:\.git\index.lock' -ErrorAction SilentlyContinue
Push-Location E:\
# scrub secrets/junk from staged
git diff --cached --name-only | ForEach-Object {
  if ($_ -match 'node_modules|/build/|/\.gradle/|/dist/|\.jar$|google-services\.json|\.jks$|\.keystore$|cloud\.yml$|database\.yml$|(^|/)\.env(\.|$)') {
    git reset -q HEAD -- $_
    Write-Output "UNSTAGE $_"
  }
}
$total = (git diff --cached --name-only | Measure-Object).Count
$nm = (git diff --cached --name-only | Where-Object { $_ -match 'node_modules' } | Measure-Object).Count
Write-Output "TOTAL_STAGED=$total NODE_MODULES=$nm"
if ($total -gt 0 -and $nm -eq 0) {
  git -c user.email="dev@rootrecord.info" -c user.name="RootRecord" commit -m "pre-SSD cutover: snapshot RootMC web/plugin/android source trees (no secrets)"
  Write-Output "COMMIT_EXIT=$LASTEXITCODE HEAD=$(git rev-parse --short HEAD)"
  git push https://github.com/RootRecord/MonoRepo.git HEAD:main
  Write-Output "PUSH_EXIT=$LASTEXITCODE"
  git ls-remote https://github.com/RootRecord/MonoRepo.git refs/heads/main
} else {
  Write-Output "SKIP commit nm=$nm total=$total"
}
Pop-Location

for ($i=0; $i -lt 36; $i++) {
  Start-Sleep 5
  $tail = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233071.txt" -Tail 25 -ErrorAction SilentlyContinue
  if ($tail -match 'exit_code:|PUSH_EXIT|COMMIT_EXIT') {
    $tail
    break
  }
  if ($i % 6 -eq 5) { Write-Output "waiting $($i*5)s..." }
}

for ($i=0; $i -lt 60; $i++) {
  Start-Sleep 10
  $meta = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233071.txt" -Head 12
  $tail = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233071.txt" -Tail 20
  if ($meta -match 'exit_code:') { Write-Output $tail; break }
  if ($tail -match 'PUSH_EXIT|COMMIT_EXIT|create mode|files changed') { Write-Output "PROGRESS:"; $tail }
  if ($i % 3 -eq 2) { Write-Output "tick $($i*10)s status=$(($meta | Select-String 'status').Line)" }
}

for ($i=0; $i -lt 60; $i++) {
  Start-Sleep 10
  $tail = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233071.txt" -Tail 30
  if ($tail -match 'exit_code:|PUSH_EXIT') { Write-Output $tail; break }
  $remote = (git -C E:\ ls-remote https://github.com/RootRecord/MonoRepo.git refs/heads/main 2>$null)
  Write-Output "t=$($i*10)s local=$(git -C E:\ rev-parse --short HEAD) remote=$remote"
  if ($remote -match (git -C E:\ rev-parse HEAD)) { Write-Output "REMOTE MATCHED"; Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233071.txt" -Tail 20; break }
}

for ($i=0; $i -lt 60; $i++) {
  Start-Sleep 10
  $tail = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233071.txt" -Tail 30
  if ($tail -match 'exit_code:|PUSH_EXIT') { Write-Output $tail; break }
  $local = git -C E:\ rev-parse HEAD
  $remote = (git -C E:\ ls-remote https://github.com/RootRecord/MonoRepo.git refs/heads/main 2>$null)
  Write-Output "t=$($i*10)s local=$($local.Substring(0,8)) remote=$remote"
  if ($remote -match $local) { Write-Output "REMOTE MATCHED"; Write-Output $tail; break }
}

# Wait for deploy finish
for ($i=0; $i -lt 90; $i++) {
  Start-Sleep 10
  $c = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233073.txt" -Raw -ErrorAction SilentlyContinue
  if ($c -match 'exit_code:') {
    Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233073.txt" -Tail 80
    break
  }
  if ($c -match 'API_EXIT|WEB_EXIT|Success|Deployed|error|Error') {
    $tail = Get-Content "C:\Users\store\.cursor\projects\d-1-Work-Stations-RootMC\terminals\233073.txt" -Tail 15
    if ($i % 3 -eq 0) { Write-Output "--- tick $($i*10)s ---"; $tail }
  } elseif ($i % 6 -eq 0) {
    Write-Output "waiting deploy... $($i*10)s"
  }
}
